public String format(LoggingEvent event) {
    try {
        if (event == null) {
            return "";
        }
        if (pattern == null || pattern.isEmpty()) {
            return event.getMessage() != null ? event.getMessage() : "";
        }
        String formatted = pattern;
        // Handle date conversion, e.g., %d{ISO8601}
        if (formatted.contains("%d{ISO8601}")) {
            java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSSZ");
            formatted = formatted.replace("%d{ISO8601}", sdf.format(new java.util.Date(event.getTimeStamp())));
        } else if (formatted.contains("%d")) {
            java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
            formatted = formatted.replace("%d", sdf.format(new java.util.Date(event.getTimeStamp())));
        }
        // Thread name
        formatted = formatted.replace("%t", event.getThreadName() != null ? event.getThreadName() : "");
        // Logging level
        formatted = formatted.replace("%p", event.getLevel() != null ? event.getLevel().toString() : "");
        // Logger name
        formatted = formatted.replace("%c", event.getLoggerName() != null ? event.getLoggerName() : "");
        // Message
        formatted = formatted.replace("%m", event.getMessage() != null ? event.getMessage() : "");
        // New line
        formatted = formatted.replace("%n", System.lineSeparator());
        return formatted;
    } catch (Exception e) {
        throw new RuntimeException("Failed to format logging event", e);
    }
