@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    if(target == null || resultMap == null){
        return;
    }
    // Vertices from the resultMap become the right partition
    Set<V> right = new java.util.HashSet<V>(resultMap.values());
    // Existing vertices in the graph become the left partition
    Set<V> left = new java.util.HashSet<V>(target.vertexSet());
    // Add all right vertices to the graph (duplicate addVertex is a no‑op)
    for (V vRight : right) {
        target.addVertex(vRight);
    }
    // Connect each vertex in the left partition to every vertex in the right partition
    for (V vLeft : left) {
        for (V vRight : right) {
            if (!target.containsEdge(vLeft, vRight) && !target.containsEdge(vRight, vLeft)) {
                target.addEdge(vLeft, vRight);
            }
        }
    }
