public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    try {
        if (!(genericType instanceof java.lang.reflect.ParameterizedType)) {
            return null;
        }
        java.lang.reflect.ParameterizedType pType = (java.lang.reflect.ParameterizedType) genericType;
        java.lang.reflect.Type raw = pType.getRawType();
        if (!(raw instanceof Class<?>)) {
            return null;
        }
        Class<?> rawClass = (Class<?>) raw;

        // Build a map from type variables of rawClass to actual types in targetType
        java.util.Map<java.lang.reflect.TypeVariable<?>, java.lang.reflect.Type> typeVarMap = new java.util.HashMap<>();
        Class<?> current = targetType;
        boolean found = false;
        while (current != null && !found) {
            // check superclass
            java.lang.reflect.Type superType = current.getGenericSuperclass();
            if (superType instanceof java.lang.reflect.ParameterizedType) {
                java.lang.reflect.ParameterizedType superPT = (java.lang.reflect.ParameterizedType) superType;
                Class<?> superRaw = (Class<?>) superPT.getRawType();
                if (superRaw == rawClass) {
                    java.lang.reflect.TypeVariable<?>[] vars = superRaw.getTypeParameters();
                    java.lang.reflect.Type[] args = superPT.getActualTypeArguments();
                    for (int i = 0; i < vars.length; i++) {
                        typeVarMap.put(vars[i], args[i]);
                    }
                    found = true;
                    break;
                }
            }
            // check interfaces
            java.lang.reflect.Type[] interfaces = current.getGenericInterfaces();
            for (java.lang.reflect.Type iface : interfaces) {
                if (iface instanceof java.lang.reflect.ParameterizedType) {
                    java.lang.reflect.ParameterizedType ifacePT = (java.lang.reflect.ParameterizedType) iface;
                    Class<?> ifaceRaw = (Class<?>) ifacePT.getRawType();
                    if (ifaceRaw == rawClass) {
                        java.lang.reflect.TypeVariable<?>[] vars = ifaceRaw.getTypeParameters();
                        java.lang.reflect.Type[] args = ifacePT.getActualTypeArguments();
                        for (int i = 0; i < vars.length; i++) {
                            typeVarMap.put(vars[i], args[i]);
                        }
                        found = true;
                        break;
                    }
                }
            }
            if (found) break;
            current = current.getSuperclass();
        }
        if (!found) {
            return null;
        }

        // Helper to resolve a Type to Class<?>
        java.util.function.Function<java.lang.reflect.Type, Class<?>> resolver = new java.util.function.Function<java.lang.reflect.Type, Class<?>>() {
            @Override
            public Class<?> apply(java.lang.reflect.Type t) {
                if (t instanceof Class<?>) {
                    return (Class<?>) t;
                } else if (t instanceof java.lang.reflect.ParameterizedType) {
                    java.lang.reflect.ParameterizedType pt = (java.lang.reflect.ParameterizedType) t;
                    java.lang.reflect.Type rawT = pt.getRawType();
                    if (rawT instanceof Class<?>) {
                        return (Class<?>) rawT;
                    } else {
                        return null;
                    }
                } else if (t instanceof java.lang.reflect.TypeVariable<?>) {
                    java.lang.reflect.Type actual = typeVarMap.get(t);
                    if (actual == null) {
                        return null;
                    }
                    return apply(actual);
                } else {
                    return null;
                }
            }
        };

        java.lang.reflect.Type[] typeArgs = pType.getActualTypeArguments();
        java.util.List<Class<?>> resultList = new java.util.ArrayList<>();
        for (java.lang.reflect.Type arg : typeArgs) {
            Class<?> clazz = resolver.apply(arg);
            if (clazz == null) {
                return null;
            }
            resultList.add(clazz);
        }
        return resultList.toArray(new Class<?>[0]);

    } catch (Exception e) {
        return null;
    }

