public synchronized void send(final String message){
    if (clients == null) return;
    final String telnetLine = message + System.lineSeparator();
    for (Object c : clients) {
        try {
            if (c instanceof PrintWriter) {
                PrintWriter out = (PrintWriter) c;
                out.print(telnetLine);
                out.flush();
            } else if (c instanceof Socket) {
                Socket sock = (Socket) c;
                OutputStream os = sock.getOutputStream();
                os.write(telnetLine.getBytes(StandardCharsets.UTF_8));
                os.flush();
            } else if (c instanceof OutputStream) {
                OutputStream os = (OutputStream) c;
                os.write(telnetLine.getBytes(StandardCharsets.UTF_8));
                os.flush();
            }
        } catch (IOException ignored) {
            // ignore or handle client removal
        }
    }
