static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    if(timeBucket <= 0){
        throw new IllegalArgumentException("timeBucket must be positive");
    }
    int y = (int)(timeBucket / 10000);
    int m = (int)(timeBucket / 100) % 100;
    int d = (int)(timeBucket % 100);
    if(d < 1 || d > 31){
        throw new IllegalArgumentException("Invalid day in timeBucket: " + timeBucket);
    }
    int newD = d - ((d - 1) % dayStep);
    // Ensure newD is within valid range for month
    if(newD < 1 || newD > 31){
        throw new IllegalArgumentException("Computed day out of bounds: " + newD);
    }
    return y * 10000L + m * 100L + newD;
}<|return|>

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("String cannot be null");
    }
    final int totalLen = str.length();
    if (index < 0 || len < 0 || index + len > totalLen) {
        throw new IndexOutOfBoundsException(
                "Index: " + index + ", Length: " + len + ", String length: " + totalLen);
    }
    int size = 0;
    int i = index;
    final int end = index + len;
    while (i < end) {
        char ch = str.charAt(i);
        if (ch <= 0x007F) { // 1-byte
            size += 1;
            i++;
        } else if (ch <= 0x07FF) { // 2-byte
            size += 2;
            i++;
        } else if (Character.isHighSurrogate(ch) && i + 1 < end
                && Character.isLowSurrogate(str.charAt(i + 1))) {
            // surrogate pair -> code point
            int codePoint = Character.toCodePoint(ch, str.charAt(i + 1));
            if (codePoint <= 0xFFFF) { // unicode BMP, 3-byte
                size += 3;
            } else { // beyond BMP
                size += 4;
            }
            i += 2;
        } else {
            // lone surrogate or other BMP code point: 3 bytes
            size += 3;
            i++;
        }
    }
    return size;
}<|return|>

