    if (candidate % 2 == 0) {
        candidate++;
    }
    while (true) {
        boolean prime = true;
        if (candidate < 2) {
            prime = false;
        } else if (candidate % 2 == 0) {
            prime = (candidate == 2);
        } else {
            int sqrt = (int) Math.sqrt(candidate);
            for (int i = 3; i <= sqrt; i += 2) {
                if (candidate % i == 0) {
                    prime = false;
                    break;
                }
            }
        }
        if (prime) {
            return candidate;
        }
        candidate += 2;
    }
