        zeroBucket = new HashSet<>();
        bucketsByLabel.add(0, zeroBucket);
    }
    // Update labels for vertices being moved
    for (Integer v : minBucket) {
        labels.set(v, 0);
    }
    // Move vertices from minLabel bucket to bucket 0
    zeroBucket.addAll(minBucket);
    // Clear the minLabel bucket
