private String parseToken(final char[] terminators){
    try {
        if (terminators == null) {
            return "";
        }
        StringBuilder token = new StringBuilder();
        int ch = peek();
        while (ch != -1) {
            char c = (char) ch;
            boolean isTerminator = false;
            for (char t : terminators) {
                if (c == t) {
                    isTerminator = true;
                    break;
                }
            }
            if (isTerminator) {
                break;
            }
            token.append(c);
            read(); // consume the character
            ch = peek();
        }
        return token.toString();
    } catch (Exception ex) {
        throw new RuntimeException("Error parsing token", ex);
    }
