private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(new ArrayList<Integer>(), 0L);
    }
    List<Integer> suffixSum = new ArrayList<>(bounds.size());
    long total = 0L;
    for (int value : bounds){
        total += value;
    }
    long currentSuffix = 0L;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        currentSuffix += bounds.get(i);
        suffixSum.add(0, Integer.valueOf((int)currentSuffix));
    }
    return new Pair<>(suffixSum, total);
