private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertices set cannot be null");
    }
    // A graph with zero or one vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 == v2) {
                continue; // skip self-comparison
            }
            // graph.containsEdge may throw if either vertex not in the graph; we catch and treat as false
            try {
                if (!graph.containsEdge(v1, v2)) {
                    return false;
                }
            } catch (Exception e) {
                return false;
            }
        }
    }
    return true;
}<|return|>

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    if (keys == null) { return bounds; }
    for (K k : keys) {
        if (k == null) {
            bounds.add(null);
            continue;
        }
        try {
            Integer keyVal = (Integer) k;
            Integer maxLower = null;
            for (K other : keys) {
                if (other == null) { continue; }
                if (other == k) { continue; }
                Integer valOther = (Integer) other;
                if (valOther <= keyVal) {
                    if (maxLower == null || valOther > maxLower) {
                        maxLower = valOther;
                    }
                }
            }
            bounds.add(maxLower);
        } catch (ClassCastException e) {
            bounds.add(null);
        }
    }
    return bounds;
