private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> upperBounds = new ArrayList<>();
    if (keys == null) {
        return upperBounds;
    }
    for (K key : keys) {
        if (key == null) {
            upperBounds.add(null);
            continue;
        }
        if (!(key instanceof Integer)) {
            // Unsupported type; add null as a placeholder
            upperBounds.add(null);
            continue;
        }
        Integer keyInt = (Integer) key;
        Integer minUpper = Integer.MAX_VALUE;
        try {
            for (K candidate : keys) {
                if (candidate == null || candidate == key) {
                    continue;
                }
                if (!(candidate instanceof Integer)) {
                    continue;
                }
                Integer candInt = (Integer) candidate;
                if (candInt.compareTo(keyInt) > 0 && candInt < minUpper) {
                    minUpper = candInt;
                }
            }
        } catch (ClassCastException e) {
            // If any element cannot be cast to Integer, treat as unsupported
            upperBounds.add(null);
            continue;
        }
        if (minUpper.equals(Integer.MAX_VALUE)) {
            upperBounds.add(null);
        } else {
            upperBounds.add(minUpper);
        }
    }
    return upperBounds;
